package mcp

import (
	mcpsdk "github.com/modelcontextprotocol/go-sdk/mcp"

	"github.com/rusher2004/new-eden-agent-toolkit/config"
	"github.com/rusher2004/new-eden-agent-toolkit/sde"
)

// registerNavigationTools adds the jump route and hauling tools, which serve
// any move through New Eden (PvP, PvE or industry), not only builds. See
// docs/superpowers/specs/2026-11-20-logistics-planning-design.md.
func registerNavigationTools(server *mcpsdk.Server, version, clientID string, store *config.Store, sdeStore *sde.Store) {
	add := func(name, desc string) *mcpsdk.Tool { return &mcpsdk.Tool{Name: name, Description: desc} }

	// Haul profiles and saved routes (written to ~/.neat/haul_profiles.yaml and routes.yaml only).
	mcpsdk.AddTool(server, add("save_haul_profile", "Save (or replace) a named hauling profile: hull, pilot, fitted hold (worked out from the ship's real fit when given shipItemId), optional pinned routes (saved in routes.yaml, or saved routes by name), and routing preferences (avoid lists, sovereignty and standings, midpoints, optimise for fuel, jumps or fatigue). Omit notes to keep the notes it has. Writes to ~/.neat/haul_profiles.yaml and routes.yaml only."), saveHaulProfileHandler(version, clientID, store, sdeStore))
	mcpsdk.AddTool(server, add("list_haul_profiles", "List saved haul profiles."), listHaulProfilesHandler(store))
	mcpsdk.AddTool(server, add("save_route", "Save (or replace) a named jump route: its systems in order, the kind of ship it's for, and the user's notes on why it goes that way. Check list_routes before planning a route between the same places, since a saved route usually reflects choices the user made on purpose. plan_jump_route costs a saved route by name, and haul profiles pin saved routes for their regular runs. Returns every value it changed. Writes to ~/.neat/routes.yaml only."), saveRouteHandler(version, clientID, store, sdeStore))
	mcpsdk.AddTool(server, add("list_routes", "List saved jump routes with their systems, ship class and the user's notes. Check it before planning a route between the same places."), listRoutesHandler(store))
	mcpsdk.AddTool(server, add("delete_route", "Delete a saved jump route from ~/.neat/routes.yaml."), deleteProfileHandler(store, (*config.Config).DeleteRoute))
	mcpsdk.AddTool(server, add("delete_haul_profile", "Delete a saved haul profile from neat's local config."), deleteProfileHandler(store, (*config.Config).DeleteHaulProfile))

	// Readiness: what the user's characters can do and where they can be (read-only).
	mcpsdk.AddTool(server, add("list_character_capabilities", "For each logged-in character, what their skills let them do in moving ships and cargo, worked out from the game's static data: which cynos they can light (standard, industrial, covert) and on which hulls they can fly, which jump bridges and conduit jumps they can open (covert, industrial, titan bridges; covert, industrial and carrier conduits), and which hauling, jump-capable and capital hulls they can fly by class. Use it to pick pilots and cyno lighters instead of reading skills yourself."), listCharacterCapabilitiesHandler(version, clientID, store, sdeStore))
	mcpsdk.AddTool(server, add("list_jump_clones", "For each logged-in character, their jump clones (where, and which implants each carries), the implants in the clone they're in now, their home station, when they can next clone jump, worked out from their last clone jump and Infomorph Synchronizing, and whether they can start one where they're docked now (jumpFromHere: yes, no, unknown or not_docked, from structures.yaml and every character's jump clones; readyNow needs both the cooldown and a known clone bay there), with how many jump clones their skills allow. Check it before planning gate travel to get a character somewhere: a clone jump is often faster."), listJumpClonesHandler(version, clientID, store, sdeStore))

	mcpsdk.AddTool(server, add("get_logistics_overview", "Start here for any move of ships, cargo or characters. One call gives, for each logged-in character: their account label, whether they're online, where they are (system with its displayed security, and the station or structure they're docked in), their ship, the cynos, bridges and conduits they can use with the hulls for each, the hauling and capital hulls they can fly, when they can next clone jump, whether they can clone jump from where they're docked, and where their jump clones are, and their jump fatigue. It also groups characters by account, flags labels the game contradicts (two characters labelled alike online at once; when one of them logged in within the last minute, it waits about a minute and checks again, since ESI can still show a character who just switched off as online), and warns about unknown accounts. Parts ESI won't give are named per character, not dropped silently."), getLogisticsOverviewHandler(version, clientID, store, sdeStore))
	mcpsdk.AddTool(server, add("list_haul_ships", "Find where the user's hauling, jump-capable and capital ships are: every assembled hauler, jump freighter, freighter, transport, blockade runner, industrial command ship, Rorqual, Black Ops, carrier, dreadnought, force auxiliary, supercarrier and titan the logged-in characters own (and a corporation's, through a character with the roles), plus any other ship with a cyno generator fitted. Each comes with its owner, item ID, class, name, the station, structure or system it's in with its displayed security, the ship it's carried in if any, and its fitted cyno generator. Use it instead of reading full asset lists to find haulers and cyno ships; pass its itemId as shipItemId and its ownerId as ownerId to estimate_ship_hold or estimate_cyno, or as shipOwnerId to save_haul_profile."), listHaulShipsHandler(version, clientID, store, sdeStore))
	mcpsdk.AddTool(server, add("compare_haul_hulls", "Compare hulls for moving cargo or ships, from the game's static data: every hold by base capacity (cargo, ship maintenance bay, fleet hangar, fuel bay and special holds), warp speed, align time, warp core strength, whether it can fit a covert ops cloak or has or can fit interdiction nullification, whether it can travel into highsec, where it can dock, its jump drive (range, fuel, fatigue and the cyno types it can use), and which bridges and conduits it can ride. Give classes (such as Jump Freighter or Deep Space Transport) or hulls; with pilotId, also which the pilot can fly and their jump range and fuel with their skills. Values are before modules and rigs."), compareHaulHullsHandler(version, clientID, store, sdeStore))

	mcpsdk.AddTool(server, add("estimate_ship_hold", "Work out a ship's fitted holds the way the game does, from its hull, fitted modules and rigs, and the pilot's skills: every hold before and after, what's already in the cargo hold and what's free, and its fitted warp speed, top speed, align time and jump range and fuel. Give an owned ship by shipItemId (its real fit and cargo are read from assets) or a hull and modules by name. Use it instead of asking the user for their cargo hold."), estimateShipHoldHandler(version, clientID, store, sdeStore))
	mcpsdk.AddTool(server, add("estimate_cyno", "Work out what lighting cynos with a ship takes, the way the game does: fuel per light and cycle length with the lighter's Cynosural Field Theory and the hull's bonuses, the fuel's volume, the fitted cargo hold, how many lights one load of fuel covers (fuel already aboard doesn't count against the hold), for an owned ship the fuel already aboard and the lights it covers, and for a number of lights the fuel needed and every load of fuel the lights take, in order: before which light and how many units to add, the fuel aboard burned first. Also says whether the generator fits the hull and which skills the lighter still needs."), estimateCynoHandler(version, clientID, store, sdeStore))

	// Routing and hauling (read-only).
	mcpsdk.AddTool(server, add("plan_jump_route", "Plan jump and gate routes between two systems for a haul profile's ship and pilot, applying their routing preferences, or validate and cost a given route; per leg light years, fuel and fatigue, and dotlan links that display each route. Each route also comes with checks worked out for the hull: the cyno types it can jump to, where it can dock at each landing (NPC stations it may use and saved structures it fits, flagging landings with nowhere to dock), how many gates a single cyno lighter travels between landings, and whether the route's fuel fits the fuel bay. Highsec entry comes from the hull's own data."), planJumpRouteHandler(version, clientID, store, sdeStore))
	mcpsdk.AddTool(server, add("plan_haul", "Pack a cargo list into loads for a haul profile's hold, each an even slice with volume by drop-off, plus round-trip route, fuel per trip, and a Multibuy list per load including fuel. With more haul profiles in with, several ships fly the trip together: their holds add up, each load is divided between them, each must manage the same route (or the call says which can't), and the result gives the cyno types they can all share."), planHaulHandler(version, clientID, store, sdeStore))
}
